// Generated from the reviewed Sacred Bill Tracker education library. Local only.
import Foundation
struct FinancialLesson: Identifiable, Codable, Hashable {
    let id: String
    let category: String
    let text: String
    var author: String { category } // Compatibility with existing card layout.
    var shareText: String { "Financial Education\nSacred Bill Tracker\n\n" + category + "\n" + text }
}
enum FinancialEducation {
    static let disclosure = "Sacred Bill Tracker provides general financial education and organizational tools. It does not provide personalized financial, investment, tax, legal, or credit advice."
    static let all: [FinancialLesson] = [
        FinancialLesson(id: "edu-01-1", category: "Budgeting", text: "A budget compares expected income with planned spending. It can be revised when either changes."),
        FinancialLesson(id: "edu-01-2", category: "Budgeting", text: "A monthly budget and a weekly cash-flow plan answer different questions: how much is available overall, and when it is available."),
        FinancialLesson(id: "edu-01-3", category: "Budgeting", text: "A budget category groups related expenses so patterns are easier to see without judging individual purchases."),
        FinancialLesson(id: "edu-01-4", category: "Budgeting", text: "An irregular expense can still be planned: an annual cost divided by twelve gives a monthly planning amount."),
        FinancialLesson(id: "edu-01-5", category: "Budgeting", text: "A budget based on take-home pay separates spendable income from taxes and deductions already withheld."),
        FinancialLesson(id: "edu-02-1", category: "Bills & Due Dates", text: "A bill's due date is different from the date a payment leaves a bank account. Processing time can matter."),
        FinancialLesson(id: "edu-02-2", category: "Bills & Due Dates", text: "Autopay schedules a payment, but it does not confirm that enough money is available or that the payment succeeded."),
        FinancialLesson(id: "edu-02-3", category: "Bills & Due Dates", text: "A reminder is a prompt to review a bill; it is not proof that a payment was sent."),
        FinancialLesson(id: "edu-02-4", category: "Bills & Due Dates", text: "Some providers allow due-date changes. Their rules and the timing of the next bill can differ."),
        FinancialLesson(id: "edu-02-5", category: "Bills & Due Dates", text: "When a bill is overdue, the provider can explain available arrangements, fees, and service consequences. An arrangement may need written confirmation."),
        FinancialLesson(id: "edu-03-1", category: "Emergency Funds", text: "An emergency fund is a reserve for unexpected costs, separate from money intended for routine bills."),
        FinancialLesson(id: "edu-03-2", category: "Emergency Funds", text: "The size of an emergency reserve depends on expenses, income stability, and other available support; there is no single amount for everyone."),
        FinancialLesson(id: "edu-03-3", category: "Emergency Funds", text: "A repair that happens every year may fit a planned savings fund better than an emergency category."),
        FinancialLesson(id: "edu-03-4", category: "Emergency Funds", text: "Easy access matters for emergency savings because unexpected expenses may arrive before a long-term investment can be sold."),
        FinancialLesson(id: "edu-03-5", category: "Emergency Funds", text: "Using part of an emergency reserve for an unexpected expense is its intended purpose; rebuilding it can be a separate goal."),
        FinancialLesson(id: "edu-04-1", category: "Saving", text: "Saving means setting aside money for later use rather than spending it immediately."),
        FinancialLesson(id: "edu-04-2", category: "Saving", text: "An automatic savings transfer moves money on a schedule; its timing still needs to fit available funds."),
        FinancialLesson(id: "edu-04-3", category: "Saving", text: "A savings goal is easier to measure when it has a purpose, an amount, and a target date."),
        FinancialLesson(id: "edu-04-4", category: "Saving", text: "A windfall is irregular income, such as a gift or bonus, rather than a dependable part of every month's budget."),
        FinancialLesson(id: "edu-04-5", category: "Saving", text: "Saving for several purposes can be tracked separately even when the money is held in one account."),
        FinancialLesson(id: "edu-05-1", category: "Checking Accounts", text: "A checking account is generally designed for everyday payments and deposits; fees and services vary by account."),
        FinancialLesson(id: "edu-05-2", category: "Checking Accounts", text: "An available balance may differ from a statement balance because deposits, holds, and pending transactions affect it."),
        FinancialLesson(id: "edu-05-3", category: "Checking Accounts", text: "A check can be deposited before the payer expects it. Writing a future date does not reliably delay processing."),
        FinancialLesson(id: "edu-05-4", category: "Checking Accounts", text: "Account maintenance fees can depend on balance or deposit conditions. The account's fee schedule describes those conditions."),
        FinancialLesson(id: "edu-05-5", category: "Checking Accounts", text: "Reconciling an account means comparing personal records with bank activity to identify missing or unexpected entries."),
        FinancialLesson(id: "edu-06-1", category: "Savings Accounts", text: "A savings account may pay interest, but its rate can change according to the account terms."),
        FinancialLesson(id: "edu-06-2", category: "Savings Accounts", text: "APY describes an annualized yield that reflects compounding; it is different from a simple stated interest rate."),
        FinancialLesson(id: "edu-06-3", category: "Savings Accounts", text: "Deposit insurance depends on the institution, account ownership, and applicable coverage rules; an app logo alone is not proof of coverage."),
        FinancialLesson(id: "edu-06-4", category: "Savings Accounts", text: "A minimum opening deposit and a minimum balance to avoid fees are different requirements."),
        FinancialLesson(id: "edu-06-5", category: "Savings Accounts", text: "A certificate of deposit usually has a stated term; accessing funds early may involve a penalty under its terms."),
        FinancialLesson(id: "edu-07-1", category: "Credit Cards", text: "A credit card purchase borrows against a credit line; the credit limit is not additional income."),
        FinancialLesson(id: "edu-07-2", category: "Credit Cards", text: "The statement balance covers a completed billing cycle, while the current balance can include newer activity."),
        FinancialLesson(id: "edu-07-3", category: "Credit Cards", text: "A purchase grace period may depend on paying the statement balance in full and on other card terms."),
        FinancialLesson(id: "edu-07-4", category: "Credit Cards", text: "Cash advances can have different fees and interest rules from ordinary card purchases."),
        FinancialLesson(id: "edu-07-5", category: "Credit Cards", text: "A card reward is only one part of its cost; interest, annual fees, and spending requirements also affect the comparison."),
        FinancialLesson(id: "edu-08-1", category: "Credit Scores", text: "A credit score summarizes information using a scoring model; different models may produce different numbers."),
        FinancialLesson(id: "edu-08-2", category: "Credit Scores", text: "Payment history is one factor commonly used in credit-scoring models, but no single action guarantees a specific score change."),
        FinancialLesson(id: "edu-08-3", category: "Credit Scores", text: "Credit utilization compares revolving balances with credit limits; it is not the same as the monthly payment amount."),
        FinancialLesson(id: "edu-08-4", category: "Credit Scores", text: "A credit report contains account information, while a credit score is a calculation based on report information."),
        FinancialLesson(id: "edu-08-5", category: "Credit Scores", text: "An error on a credit report can be disputed through the relevant reporting company; the outcome depends on the facts reviewed."),
        FinancialLesson(id: "edu-09-1", category: "Debt", text: "A debt balance is the amount owed at a point in time; interest and fees may change that balance."),
        FinancialLesson(id: "edu-09-2", category: "Debt", text: "Secured debt is connected to collateral that a lender may claim under the agreement if obligations are not met."),
        FinancialLesson(id: "edu-09-3", category: "Debt", text: "Unsecured debt does not use specified collateral, but missed payments can still have contractual and legal consequences."),
        FinancialLesson(id: "edu-09-4", category: "Debt", text: "Debt consolidation combines obligations into another loan or account; a lower payment does not necessarily mean a lower total cost."),
        FinancialLesson(id: "edu-09-5", category: "Debt", text: "Debt repayment methods differ in their focus, such as highest interest rate or smallest balance; costs and practical needs can vary."),
        FinancialLesson(id: "edu-10-1", category: "Interest", text: "Interest is a cost of borrowing or a payment for certain savings, usually expressed as a rate over time."),
        FinancialLesson(id: "edu-10-2", category: "Interest", text: "Simple interest is calculated on principal; compounding also takes accumulated interest into account."),
        FinancialLesson(id: "edu-10-3", category: "Interest", text: "A variable interest rate can change based on the terms of the product, sometimes by reference to an index."),
        FinancialLesson(id: "edu-10-4", category: "Interest", text: "A fixed rate stays the same for the period specified in the agreement, which may not be the entire life of every product."),
        FinancialLesson(id: "edu-10-5", category: "Interest", text: "The same interest rate applied to different balances can produce different dollar amounts of interest."),
        FinancialLesson(id: "edu-11-1", category: "APR", text: "APR means annual percentage rate, an annualized borrowing-cost measure whose included fees depend on the product."),
        FinancialLesson(id: "edu-11-2", category: "APR", text: "A loan's APR can differ from its interest rate when applicable finance charges are included."),
        FinancialLesson(id: "edu-11-3", category: "APR", text: "A promotional APR usually has conditions and an end date; the rate afterward may be different."),
        FinancialLesson(id: "edu-11-4", category: "APR", text: "A credit card can have separate APRs for purchases, balance transfers, and cash advances."),
        FinancialLesson(id: "edu-11-5", category: "APR", text: "APR alone does not show the total dollar cost of a loan; the amount borrowed and repayment term also matter."),
        FinancialLesson(id: "edu-12-1", category: "Minimum Payments", text: "A minimum payment is the smallest required payment for a billing period, not necessarily the amount needed to avoid interest."),
        FinancialLesson(id: "edu-12-2", category: "Minimum Payments", text: "Paying only the minimum can extend repayment and increase total interest when a balance continues to accrue interest."),
        FinancialLesson(id: "edu-12-3", category: "Minimum Payments", text: "A card's minimum payment may change as the balance, interest, fees, or formula changes."),
        FinancialLesson(id: "edu-12-4", category: "Minimum Payments", text: "An extra payment does not always replace the next scheduled payment; the lender's processing rules determine how it is applied."),
        FinancialLesson(id: "edu-12-5", category: "Minimum Payments", text: "A credit card statement may show repayment estimates; those estimates depend on the assumptions stated on the bill."),
        FinancialLesson(id: "edu-13-1", category: "Loans", text: "Loan principal is the amount borrowed or the remaining borrowed balance, separate from interest and some charges."),
        FinancialLesson(id: "edu-13-2", category: "Loans", text: "A longer loan term may lower scheduled payments while increasing total interest, depending on the rate and fees."),
        FinancialLesson(id: "edu-13-3", category: "Loans", text: "An amortization schedule shows how scheduled payments are allocated between principal and interest over time."),
        FinancialLesson(id: "edu-13-4", category: "Loans", text: "A prepayment penalty is a charge that may apply to early repayment if the agreement includes one."),
        FinancialLesson(id: "edu-13-5", category: "Loans", text: "A co-signer accepts repayment responsibility under the agreement; co-signing is more than providing a reference."),
        FinancialLesson(id: "edu-14-1", category: "Auto Loans", text: "The price of a vehicle and the total amount financed can differ when taxes, fees, or optional products are included."),
        FinancialLesson(id: "edu-14-2", category: "Auto Loans", text: "A trade-in with an outstanding loan may add unpaid debt to a new loan if its value is below the payoff amount."),
        FinancialLesson(id: "edu-14-3", category: "Auto Loans", text: "A loan payoff quote can differ from the displayed balance because it may include interest through a specific date."),
        FinancialLesson(id: "edu-14-4", category: "Auto Loans", text: "Vehicle ownership costs can include insurance, maintenance, registration, and fuel in addition to a loan payment."),
        FinancialLesson(id: "edu-14-5", category: "Auto Loans", text: "A repossession does not always settle an auto loan completely; a remaining balance may depend on sale proceeds and applicable rules."),
        FinancialLesson(id: "edu-15-1", category: "Mortgages", text: "A mortgage payment may include principal, interest, and an escrow amount for property taxes or insurance."),
        FinancialLesson(id: "edu-15-2", category: "Mortgages", text: "Escrow payments can change when estimated property taxes or insurance costs change, even with a fixed-rate mortgage."),
        FinancialLesson(id: "edu-15-3", category: "Mortgages", text: "A down payment and closing costs are different parts of the money needed for a home purchase."),
        FinancialLesson(id: "edu-15-4", category: "Mortgages", text: "An adjustable-rate mortgage has rules for when its rate changes and how large those changes can be."),
        FinancialLesson(id: "edu-15-5", category: "Mortgages", text: "A mortgage preapproval is not a final loan guarantee; underwriting and property requirements still apply."),
        FinancialLesson(id: "edu-16-1", category: "Insurance Basics", text: "An insurance premium is the price of coverage; a deductible is an amount the policy may require the insured to pay on a covered claim."),
        FinancialLesson(id: "edu-16-2", category: "Insurance Basics", text: "A policy limit is the maximum coverage for a specified benefit, subject to policy terms and exclusions."),
        FinancialLesson(id: "edu-16-3", category: "Insurance Basics", text: "An exclusion identifies something a policy does not cover, even when a similar event might be covered."),
        FinancialLesson(id: "edu-16-4", category: "Insurance Basics", text: "A lower premium may come with different deductibles or coverage, so price alone does not describe a policy."),
        FinancialLesson(id: "edu-16-5", category: "Insurance Basics", text: "A beneficiary is a person or entity designated to receive certain policy benefits under the contract."),
        FinancialLesson(id: "edu-17-1", category: "Taxes Basics", text: "Tax rules depend on jurisdiction and personal circumstances; general education does not determine an individual's filing obligations."),
        FinancialLesson(id: "edu-17-2", category: "Taxes Basics", text: "A tax deduction and a tax credit affect a calculation differently; eligibility and value depend on applicable rules."),
        FinancialLesson(id: "edu-17-3", category: "Taxes Basics", text: "Tax withholding is money paid toward taxes during the year, not a final calculation of the total tax owed."),
        FinancialLesson(id: "edu-17-4", category: "Taxes Basics", text: "Records of income and expenses can support tax preparation, but keeping a receipt does not automatically make an expense deductible."),
        FinancialLesson(id: "edu-17-5", category: "Taxes Basics", text: "A tax refund can reflect payments exceeding the final tax due; it is not necessarily a separate source of earned income."),
        FinancialLesson(id: "edu-18-1", category: "Paychecks", text: "Gross pay is earnings before deductions; net pay is the amount remaining after deductions."),
        FinancialLesson(id: "edu-18-2", category: "Paychecks", text: "A pay stub can list taxes, benefits, and other deductions that explain the difference between gross and net pay."),
        FinancialLesson(id: "edu-18-3", category: "Paychecks", text: "Biweekly pay means every two weeks; twice-monthly pay means two scheduled paydays each month."),
        FinancialLesson(id: "edu-18-4", category: "Paychecks", text: "Overtime, bonuses, and variable hours can make one paycheck different from another."),
        FinancialLesson(id: "edu-18-5", category: "Paychecks", text: "A payroll correction may appear in a later pay period, so the date of a correction and the original work period can differ."),
        FinancialLesson(id: "edu-19-1", category: "Direct Deposit", text: "Direct deposit sends a payment electronically to a designated account using the payer's payroll or payment process."),
        FinancialLesson(id: "edu-19-2", category: "Direct Deposit", text: "A direct-deposit change may require processing time; the next payment may still use the previous instructions."),
        FinancialLesson(id: "edu-19-3", category: "Direct Deposit", text: "Early access to a deposit offered by some institutions can depend on when payment information is received."),
        FinancialLesson(id: "edu-19-4", category: "Direct Deposit", text: "Some payroll systems allow deposits to be divided among accounts; availability and limits depend on the employer's system."),
        FinancialLesson(id: "edu-19-5", category: "Direct Deposit", text: "A routing number identifies a financial institution, while an account number identifies a particular account; both are sensitive information."),
        FinancialLesson(id: "edu-20-1", category: "Income", text: "Income received once is different from income expected regularly; separating them can make a spending plan clearer."),
        FinancialLesson(id: "edu-20-2", category: "Income", text: "Revenue is money received by a business before expenses; it is not the same as profit or personal take-home pay."),
        FinancialLesson(id: "edu-20-3", category: "Income", text: "A cash-flow plan tracks when money arrives, not just the total amount expected over a month."),
        FinancialLesson(id: "edu-20-4", category: "Income", text: "Irregular income can be reviewed over multiple periods to understand variability rather than treating one unusually high period as typical."),
        FinancialLesson(id: "edu-20-5", category: "Income", text: "A reimbursement repays an expense already incurred; counting both the reimbursement and the original cost correctly avoids distorted totals."),
        FinancialLesson(id: "edu-21-1", category: "Needs vs. Wants", text: "A need supports essential living or obligations, while a want adds preference or convenience; the distinction depends on circumstances."),
        FinancialLesson(id: "edu-21-2", category: "Needs vs. Wants", text: "An expense can contain both need and want elements, such as basic transportation and optional upgrades."),
        FinancialLesson(id: "edu-21-3", category: "Needs vs. Wants", text: "Calling a purchase a want does not make it wrong; categories are tools for planning rather than moral judgments."),
        FinancialLesson(id: "edu-21-4", category: "Needs vs. Wants", text: "Priorities can change after a move, illness, or job change, so spending categories may need review."),
        FinancialLesson(id: "edu-21-5", category: "Needs vs. Wants", text: "A low price does not make an item necessary; usefulness and affordability are separate questions."),
        FinancialLesson(id: "edu-22-1", category: "Spending Habits", text: "Small recurring purchases can form a noticeable monthly total even when each transaction is modest."),
        FinancialLesson(id: "edu-22-2", category: "Spending Habits", text: "A spending pattern is easier to identify from several transactions than from a single unusual purchase."),
        FinancialLesson(id: "edu-22-3", category: "Spending Habits", text: "A unit price compares cost per measure, such as per ounce, but waste and storage needs can affect the practical value."),
        FinancialLesson(id: "edu-22-4", category: "Spending Habits", text: "A planned purchase list separates intended spending from decisions made while browsing."),
        FinancialLesson(id: "edu-22-5", category: "Spending Habits", text: "A discount reduces a listed price, but buying an unplanned item still uses money that could serve another purpose."),
        FinancialLesson(id: "edu-23-1", category: "Subscriptions", text: "A free trial may convert to a paid subscription unless it is canceled under the provider's terms."),
        FinancialLesson(id: "edu-23-2", category: "Subscriptions", text: "Deleting an app does not necessarily cancel a subscription billed through an app store or another provider."),
        FinancialLesson(id: "edu-23-3", category: "Subscriptions", text: "A cancellation confirmation helps document a request; access and renewal dates can differ after cancellation."),
        FinancialLesson(id: "edu-23-4", category: "Subscriptions", text: "An annual subscription's monthly equivalent can help comparison, but its charge may still be collected all at once."),
        FinancialLesson(id: "edu-23-5", category: "Subscriptions", text: "A subscription review compares ongoing cost with current use, including services that renew less often than monthly."),
        FinancialLesson(id: "edu-24-1", category: "Late Fees", text: "A late fee is separate from the original bill amount and may be governed by the agreement and applicable rules."),
        FinancialLesson(id: "edu-24-2", category: "Late Fees", text: "A payment submitted on a due date may be treated differently depending on the provider's cutoff time and accepted method."),
        FinancialLesson(id: "edu-24-3", category: "Late Fees", text: "A late-fee waiver may be available in some circumstances, but it is not guaranteed."),
        FinancialLesson(id: "edu-24-4", category: "Late Fees", text: "A late payment and a credit-report entry are not identical events; reporting timing and policies can differ."),
        FinancialLesson(id: "edu-24-5", category: "Late Fees", text: "A payment arrangement can change a schedule without removing every fee; its written terms explain what changes."),
        FinancialLesson(id: "edu-25-1", category: "Overdrafts", text: "An overdraft occurs when an account transaction exceeds available funds and the institution pays it under its rules."),
        FinancialLesson(id: "edu-25-2", category: "Overdrafts", text: "An insufficient-funds transaction may be declined or returned rather than paid; the consequences depend on the account and payment terms."),
        FinancialLesson(id: "edu-25-3", category: "Overdrafts", text: "Pending holds can reduce available funds before a final transaction amount posts."),
        FinancialLesson(id: "edu-25-4", category: "Overdrafts", text: "Linking another account for transfers may have its own fees and limits; it is not necessarily free overdraft protection."),
        FinancialLesson(id: "edu-25-5", category: "Overdrafts", text: "A low-balance alert provides information but does not stop every transaction or guarantee that fees will be avoided."),
        FinancialLesson(id: "edu-26-1", category: "Financial Goals", text: "A financial goal names a desired result; a plan describes the steps and resources intended to support it."),
        FinancialLesson(id: "edu-26-2", category: "Financial Goals", text: "A target date helps translate a savings goal into smaller planning amounts, though circumstances may require adjustments."),
        FinancialLesson(id: "edu-26-3", category: "Financial Goals", text: "Progress can be measured in actions as well as dollars, such as reviewing bills or organizing records."),
        FinancialLesson(id: "edu-26-4", category: "Financial Goals", text: "Two goals can compete for the same funds; identifying the tradeoff makes a plan more transparent."),
        FinancialLesson(id: "edu-26-5", category: "Financial Goals", text: "A revised goal is not automatically a failed goal; changing information can justify a different amount or timeline."),
        FinancialLesson(id: "edu-27-1", category: "Sinking Funds", text: "A sinking fund sets aside money for a known future expense, such as annual registration or a planned repair."),
        FinancialLesson(id: "edu-27-2", category: "Sinking Funds", text: "A sinking fund differs from an emergency reserve because the expense is anticipated rather than unexpected."),
        FinancialLesson(id: "edu-27-3", category: "Sinking Funds", text: "Dividing a known cost by the number of saving periods gives a planning contribution, before any interest or price change."),
        FinancialLesson(id: "edu-27-4", category: "Sinking Funds", text: "Money set aside for an annual bill is not necessarily available for unrelated spending even if it is in the same bank account."),
        FinancialLesson(id: "edu-27-5", category: "Sinking Funds", text: "Reviewing a planned expense estimate can reveal whether its savings target still matches current prices."),
        FinancialLesson(id: "edu-28-1", category: "Retirement Basics", text: "A retirement account is a type of account with particular rules; the investments inside it are a separate choice."),
        FinancialLesson(id: "edu-28-2", category: "Retirement Basics", text: "An employer match can depend on contribution rules and eligibility, so the plan documents matter."),
        FinancialLesson(id: "edu-28-3", category: "Retirement Basics", text: "Vesting describes when certain employer contributions become the employee's to keep under a retirement plan."),
        FinancialLesson(id: "edu-28-4", category: "Retirement Basics", text: "Traditional and Roth tax treatment differ; which rules apply depends on the account and the person's circumstances."),
        FinancialLesson(id: "edu-28-5", category: "Retirement Basics", text: "Retirement contributions and withdrawals may have limits or tax consequences that change over time; current official guidance matters."),
        FinancialLesson(id: "edu-29-1", category: "Investing Basics", text: "An investment can gain or lose value; past performance does not establish a future return."),
        FinancialLesson(id: "edu-29-2", category: "Investing Basics", text: "Diversification spreads exposure across investments, but it does not remove all risk or guarantee against losses."),
        FinancialLesson(id: "edu-29-3", category: "Investing Basics", text: "A stock represents an ownership interest, while a bond generally represents lending under specified terms."),
        FinancialLesson(id: "edu-29-4", category: "Investing Basics", text: "Investment fees reduce the amount retained by an investor and can apply even during periods of losses."),
        FinancialLesson(id: "edu-29-5", category: "Investing Basics", text: "Liquidity describes how readily an asset can be converted to cash, sometimes with a cost or price concession."),
        FinancialLesson(id: "edu-30-1", category: "Compound Growth", text: "Compounding occurs when accumulated earnings also participate in later growth; actual investment returns can vary or be negative."),
        FinancialLesson(id: "edu-30-2", category: "Compound Growth", text: "At a hypothetical fixed 5% annual rate, $100 becomes $105 after one year and $110.25 after two, before taxes or fees; this is not a forecast."),
        FinancialLesson(id: "edu-30-3", category: "Compound Growth", text: "More frequent compounding can affect an account's yield, which is why APY and a nominal rate may differ."),
        FinancialLesson(id: "edu-30-4", category: "Compound Growth", text: "Compounding can also increase borrowing costs when unpaid interest is added to a balance under the loan's terms."),
        FinancialLesson(id: "edu-30-5", category: "Compound Growth", text: "A compound-growth illustration depends on assumptions about rates, time, contributions, and costs; changing them changes the result."),
        FinancialLesson(id: "edu-31-1", category: "Fraud & Scam Awareness", text: "A message demanding urgent payment can be a scam tactic; a claimed identity is not proof that the sender is genuine."),
        FinancialLesson(id: "edu-31-2", category: "Fraud & Scam Awareness", text: "A request to pay a supposed bill with gift cards is a warning sign of fraud."),
        FinancialLesson(id: "edu-31-3", category: "Fraud & Scam Awareness", text: "Contact details found independently from a trusted statement or official site are safer to verify than a link in an unexpected message."),
        FinancialLesson(id: "edu-31-4", category: "Fraud & Scam Awareness", text: "One-time security codes can give access to an account; sharing them with an unexpected caller can compromise it."),
        FinancialLesson(id: "edu-31-5", category: "Fraud & Scam Awareness", text: "A promise of guaranteed high investment returns with little risk is a warning sign, not evidence of a legitimate opportunity."),
    ]
    static var categories: [String] { Array(Set(all.map(\.category))).sorted() }
    static func lesson(day: Int, category: String? = nil) -> FinancialLesson {
        let filtered = all.filter { category == nil || $0.category == category }
        let pool = filtered.isEmpty ? all : filtered
        return pool[((day % pool.count) + pool.count) % pool.count]
    }
    static func day(_ date: Date = Date()) -> Int {
        let calendar = Calendar(identifier: .gregorian)
        return calendar.dateComponents([.day], from: Date(timeIntervalSince1970: 0), to: calendar.startOfDay(for: date)).day ?? 0
    }
}
